// Subset Google Sans to ASCII plus every character in the shipped translations.
// Regenerated by `npm run build:sans`; the full font is in scripts/assets.
const fs = require('fs');
const path = require('path');
const subsetFont = require('subset-font');
const fontkit = require('fontkit');

const ROOT = path.resolve(__dirname, '..');
const FULL_FONT = path.join(ROOT, 'scripts/assets/GoogleSans-var-full.woff2');
const OUTPUT = path.join(ROOT, 'src/webroot/fonts/GoogleSans-var.woff2');

function collectCharacters() {
  const chars = new Set();
  for (let code = 32; code < 127; code++) chars.add(String.fromCharCode(code));

  const langDir = path.join(ROOT, 'src/webroot/lang');
  const files = [];
  const walk = dir => {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.name.endsWith('.json')) files.push(full);
    }
  };
  walk(langDir);
  for (const file of files) {
    for (const char of fs.readFileSync(file, 'utf8')) chars.add(char);
  }
  return chars;
}

async function main() {
  const fullBuffer = fs.readFileSync(FULL_FONT);
  const chars = collectCharacters();
  const text = [...chars].join('');
  const subset = await subsetFont(fullBuffer, text, { targetFormat: 'woff2' });

  const full = fontkit.openSync(FULL_FONT);
  const check = fontkit.create(subset);
  const missing = [...chars].filter(char => {
    const code = char.codePointAt(0);
    return code !== undefined && code > 32
      && full.hasGlyphForCodePoint(code)
      && !check.hasGlyphForCodePoint(code);
  });
  if (missing.length) {
    console.warn(`Warning: Google Sans subset lost supported glyphs: ${missing.join('')}`);
  }

  fs.writeFileSync(OUTPUT, subset);
  console.log(
    `Google Sans subset: ${chars.size} chars, ${(subset.length / 1024).toFixed(1)} KB ` +
    `(from ${(fullBuffer.length / 1024).toFixed(1)} KB)`
  );
}

main().catch(error => {
  console.error(error);
  process.exit(1);
});
